mapper.select:
select 

from info_publishs a
where id = #{id,jdbcType=BIGINT}

select

from info_publishs a

    left join (
        select distinct pc.publishs_id from info_publishs_safe_company pc where pc.safe_company_id in (select u.safe_company_id from info_safe_user u where u.user_id = #{currentUserId,jdbcType=BIGINT})
    ) u on a.id = u.publishs_id


ORDER by a.create_time desc limit #{pageIndex} , #{pageSize}
